package com.mo.economy_system.common.transfer;import static org.junit.jupiter.api.Assertions.*;import java.util.UUID;import org.junit.jupiter.api.Test;
class CheckedFileTransferControlJsonCodecTest{@Test void roundTripsAllStatuses(){UUID id=UUID.randomUUID();for(var value:new CheckedFileTransferControl[]{CheckedFileTransferControl.ready(id,18001,"0".repeat(64)),CheckedFileTransferControl.complete(id,18001,"0".repeat(64)),CheckedFileTransferControl.error(CheckedFileTransferControlStatus.DECLINED,"DECLINED"),CheckedFileTransferControl.error(CheckedFileTransferControlStatus.NOT_FOUND,"NOT_FOUND"),CheckedFileTransferControl.error(CheckedFileTransferControlStatus.FAILED,"SNAPSHOT_FAILED")})assertEquals(value,CheckedFileTransferControlJsonCodec.decode(CheckedFileTransferControlJsonCodec.encode(value)));}@Test void rejectsDuplicateUnknownWrongTypesAndBadMetadata(){assertThrows(IllegalArgumentException.class,()->CheckedFileTransferControlJsonCodec.decode("{\"schema\":1,\"schema\":1,\"status\":\"FAILED\",\"errorCode\":\"X\"}"));assertThrows(IllegalArgumentException.class,()->CheckedFileTransferControlJsonCodec.decode("{\"schema\":1,\"status\":\"FAILED\",\"errorCode\":\"X\",\"extra\":1}"));assertThrows(IllegalArgumentException.class,()->CheckedFileTransferControlJsonCodec.decode("{\"schema\":\"1\",\"status\":\"FAILED\",\"errorCode\":\"X\"}"));assertThrows(IllegalArgumentException.class,()->CheckedFileTransferControl.ready(UUID.randomUUID(),-1,"0".repeat(64)));}}
